import html
import os
import re
import zipfile
import xml.etree.ElementTree as ET
from datetime import datetime, timezone


PPTX_PATH = r"C:\Users\ndoansuan1.IXAS\Downloads\20260601_No131_Keyence評価_edite-for-AI-working.pptx"
OUTPUT_PATH = r"C:\Users\ndoansuan1.IXAS\Desktop\プロコン対応\No131_Keyence評価_証拠まとめ.xlsx"

NS = {
    "p": "http://schemas.openxmlformats.org/presentationml/2006/main",
    "a": "http://schemas.openxmlformats.org/drawingml/2006/main",
}


def qn(ns, tag):
    uris = {
        "a": "http://schemas.openxmlformats.org/drawingml/2006/main",
        "p": "http://schemas.openxmlformats.org/presentationml/2006/main",
        "r": "http://schemas.openxmlformats.org/officeDocument/2006/relationships",
        "ws": "http://schemas.openxmlformats.org/spreadsheetml/2006/main",
    }
    return f"{{{uris[ns]}}}{tag}"


def slide_number(path):
    return int(re.search(r"slide(\d+)\.xml", path).group(1))


def shape_position(el):
    xfrm = el.find(".//a:xfrm", NS)
    if xfrm is None:
        return (0, 0)
    off = xfrm.find("a:off", NS)
    if off is None:
        return (0, 0)
    return (int(off.attrib.get("y", 0)), int(off.attrib.get("x", 0)))


def texts_from(parent):
    paragraphs = []
    for para in parent.findall(".//a:p", NS):
        runs = []
        for text in para.findall(".//a:t", NS):
            if text.text:
                runs.append(text.text)
        line = "".join(runs).strip()
        if line:
            paragraphs.append(line)
    return "\n".join(paragraphs).strip()


def is_title_shape(shape):
    ph = shape.find(".//p:nvPr/p:ph", NS)
    if ph is not None and ph.attrib.get("type") in {"title", "ctrTitle", "subTitle"}:
        return True
    return False


def extract_slides(pptx_path):
    slides = []
    with zipfile.ZipFile(pptx_path) as pptx:
        slide_paths = sorted(
            [
                name
                for name in pptx.namelist()
                if name.startswith("ppt/slides/slide") and name.endswith(".xml")
            ],
            key=slide_number,
        )
        for slide_path in slide_paths:
            root = ET.fromstring(pptx.read(slide_path))
            elements = []

            for shape in root.findall(".//p:sp", NS):
                text = texts_from(shape)
                if text:
                    elements.append(
                        {
                            "kind": "text",
                            "pos": shape_position(shape),
                            "text": text,
                            "bold": is_title_shape(shape),
                        }
                    )

            for frame in root.findall(".//p:graphicFrame", NS):
                table = frame.find(".//a:tbl", NS)
                if table is None:
                    continue
                rows = []
                for tr in table.findall("a:tr", NS):
                    row = []
                    for tc in tr.findall("a:tc", NS):
                        row.append(texts_from(tc))
                    rows.append(row)
                if rows:
                    elements.append(
                        {
                            "kind": "table",
                            "pos": shape_position(frame),
                            "rows": rows,
                        }
                    )

            slides.append(sorted(elements, key=lambda item: item["pos"]))
    return slides


def col_name(index):
    name = ""
    while index:
        index, rem = divmod(index - 1, 26)
        name = chr(65 + rem) + name
    return name


def cell_xml(row, col, value, style=0):
    ref = f"{col_name(col)}{row}"
    style_attr = f' s="{style}"' if style else ""
    escaped = html.escape(value or "")
    return f'<c r="{ref}" t="inlineStr"{style_attr}><is><t xml:space="preserve">{escaped}</t></is></c>'


def worksheet_xml(cells, merges, col_widths):
    max_row = max((row for row, _, _, _ in cells), default=1)
    max_col = max((col for _, col, _, _ in cells), default=1)
    by_row = {}
    for row, col, value, style in cells:
        by_row.setdefault(row, []).append((col, value, style))

    cols = []
    for col in range(1, max_col + 1):
        width = min(max(col_widths.get(col, 12), 8), 45)
        cols.append(f'<col min="{col}" max="{col}" width="{width}" customWidth="1"/>')

    rows = []
    for row in range(1, max_row + 1):
        row_cells = [
            cell_xml(row, col, value, style)
            for col, value, style in sorted(by_row.get(row, []), key=lambda item: item[0])
        ]
        rows.append(f'<row r="{row}">{"".join(row_cells)}</row>')

    merge_xml = ""
    if merges:
        merge_xml = f'<mergeCells count="{len(merges)}">' + "".join(
            f'<mergeCell ref="{ref}"/>' for ref in merges
        ) + "</mergeCells>"

    return (
        '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
        '<worksheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
        'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
        f"<cols>{''.join(cols)}</cols><sheetData>{''.join(rows)}</sheetData>{merge_xml}"
        '<pageMargins left="0.7" right="0.7" top="0.75" bottom="0.75" header="0.3" footer="0.3"/>'
        "</worksheet>"
    )


def build_sheet(slide_elements):
    cells = []
    merges = []
    widths = {}
    row_cursor = 1

    for element in slide_elements:
        if element["kind"] == "text":
            cells.append((row_cursor, 1, element["text"], 1))
            merges.append(f"A{row_cursor}:H{row_cursor}")
            widths[1] = max(widths.get(1, 0), min(len(element["text"]) + 4, 45))
            row_cursor += 2
            continue

        rows = element["rows"]
        for r_offset, source_row in enumerate(rows):
            target_row = row_cursor + r_offset
            for c_offset, value in enumerate(source_row):
                target_col = 1 + c_offset
                style = 2 if r_offset == 0 else 3
                cells.append((target_row, target_col, value, style))
                width_seed = max((len(line) for line in value.splitlines()), default=0) + 2
                widths[target_col] = max(widths.get(target_col, 0), width_seed)
        row_cursor += len(rows) + 2

    return cells, merges, widths


def write_xlsx(slides, output_path):
    now = datetime.now(timezone.utc).strftime("%Y-%m-%dT%H:%M:%SZ")
    sheet_count = len(slides)

    workbook_sheets = []
    workbook_rels = []
    content_overrides = [
        '<Default Extension="rels" ContentType="application/vnd.openxmlformats-package.relationships+xml"/>',
        '<Default Extension="xml" ContentType="application/xml"/>',
        '<Override PartName="/xl/workbook.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.sheet.main+xml"/>',
        '<Override PartName="/xl/styles.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.styles+xml"/>',
        '<Override PartName="/docProps/core.xml" ContentType="application/vnd.openxmlformats-package.core-properties+xml"/>',
        '<Override PartName="/docProps/app.xml" ContentType="application/vnd.openxmlformats-officedocument.extended-properties+xml"/>',
    ]
    sheet_files = {}

    for idx, slide in enumerate(slides, start=1):
        sheet_name = f"Slide {idx}"
        workbook_sheets.append(f'<sheet name="{sheet_name}" sheetId="{idx}" r:id="rId{idx}"/>')
        workbook_rels.append(
            f'<Relationship Id="rId{idx}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/worksheet" Target="worksheets/sheet{idx}.xml"/>'
        )
        content_overrides.append(
            f'<Override PartName="/xl/worksheets/sheet{idx}.xml" ContentType="application/vnd.openxmlformats-officedocument.spreadsheetml.worksheet+xml"/>'
        )
        cells, merges, widths = build_sheet(slide)
        sheet_files[f"xl/worksheets/sheet{idx}.xml"] = worksheet_xml(cells, merges, widths)

    workbook_rels.append(
        f'<Relationship Id="rId{sheet_count + 1}" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/styles" Target="styles.xml"/>'
    )

    styles = """<?xml version="1.0" encoding="UTF-8" standalone="yes"?>
<styleSheet xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main">
  <fonts count="2"><font><sz val="11"/><name val="Yu Gothic"/></font><font><b/><sz val="11"/><name val="Yu Gothic"/></font></fonts>
  <fills count="3"><fill><patternFill patternType="none"/></fill><fill><patternFill patternType="gray125"/></fill><fill><patternFill patternType="solid"><fgColor rgb="FFEAEFF7"/><bgColor indexed="64"/></patternFill></fill></fills>
  <borders count="2"><border><left/><right/><top/><bottom/><diagonal/></border><border><left style="thin"><color auto="1"/></left><right style="thin"><color auto="1"/></right><top style="thin"><color auto="1"/></top><bottom style="thin"><color auto="1"/></bottom><diagonal/></border></borders>
  <cellStyleXfs count="1"><xf numFmtId="0" fontId="0" fillId="0" borderId="0"/></cellStyleXfs>
  <cellXfs count="4"><xf numFmtId="0" fontId="0" fillId="0" borderId="0" xfId="0"/><xf numFmtId="0" fontId="1" fillId="0" borderId="0" xfId="0" applyFont="1"/><xf numFmtId="0" fontId="1" fillId="2" borderId="1" xfId="0" applyFont="1" applyFill="1" applyBorder="1"/><xf numFmtId="0" fontId="0" fillId="0" borderId="1" xfId="0" applyBorder="1"/></cellXfs>
  <cellStyles count="1"><cellStyle name="Normal" xfId="0" builtinId="0"/></cellStyles>
</styleSheet>"""

    files = {
        "[Content_Types].xml": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Types xmlns="http://schemas.openxmlformats.org/package/2006/content-types">'
            + "".join(content_overrides)
            + "</Types>"
        ),
        "_rels/.rels": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            '<Relationship Id="rId1" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/officeDocument" Target="xl/workbook.xml"/>'
            '<Relationship Id="rId2" Type="http://schemas.openxmlformats.org/package/2006/relationships/metadata/core-properties" Target="docProps/core.xml"/>'
            '<Relationship Id="rId3" Type="http://schemas.openxmlformats.org/officeDocument/2006/relationships/extended-properties" Target="docProps/app.xml"/>'
            "</Relationships>"
        ),
        "xl/workbook.xml": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<workbook xmlns="http://schemas.openxmlformats.org/spreadsheetml/2006/main" '
            'xmlns:r="http://schemas.openxmlformats.org/officeDocument/2006/relationships">'
            f"<sheets>{''.join(workbook_sheets)}</sheets></workbook>"
        ),
        "xl/_rels/workbook.xml.rels": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Relationships xmlns="http://schemas.openxmlformats.org/package/2006/relationships">'
            + "".join(workbook_rels)
            + "</Relationships>"
        ),
        "xl/styles.xml": styles,
        "docProps/core.xml": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<cp:coreProperties xmlns:cp="http://schemas.openxmlformats.org/package/2006/metadata/core-properties" '
            'xmlns:dc="http://purl.org/dc/elements/1.1/" xmlns:dcterms="http://purl.org/dc/terms/" '
            'xmlns:dcmitype="http://purl.org/dc/dcmitype/" xmlns:xsi="http://www.w3.org/2001/XMLSchema-instance">'
            "<dc:creator>Codex</dc:creator><cp:lastModifiedBy>Codex</cp:lastModifiedBy>"
            f'<dcterms:created xsi:type="dcterms:W3CDTF">{now}</dcterms:created>'
            f'<dcterms:modified xsi:type="dcterms:W3CDTF">{now}</dcterms:modified>'
            "</cp:coreProperties>"
        ),
        "docProps/app.xml": (
            '<?xml version="1.0" encoding="UTF-8" standalone="yes"?>'
            '<Properties xmlns="http://schemas.openxmlformats.org/officeDocument/2006/extended-properties" '
            'xmlns:vt="http://schemas.openxmlformats.org/officeDocument/2006/docPropsVTypes">'
            "<Application>Microsoft Excel</Application>"
            f"<Worksheets>{sheet_count}</Worksheets>"
            "</Properties>"
        ),
    }
    files.update(sheet_files)

    if os.path.exists(output_path):
        os.remove(output_path)
    with zipfile.ZipFile(output_path, "w", compression=zipfile.ZIP_DEFLATED) as xlsx:
        for name, data in files.items():
            xlsx.writestr(name, data.encode("utf-8"))


def main():
    slides = extract_slides(PPTX_PATH)
    write_xlsx(slides, OUTPUT_PATH)
    print(f"Wrote {OUTPUT_PATH}")
    print(f"Slides: {len(slides)}")


if __name__ == "__main__":
    main()

